import json,re
from pathlib import Path
root=Path('.')
route_text=Path('src/router/index.ts').read_text(encoding='utf-8')
routes=[]
for line in route_text.splitlines():
 m=re.search(r"\{ path: '([^']*)'.*component: \(\) => import\('\.\./views/([^']+)'\)",line)
 if m: routes.append({'pattern':'/'+m[1],'source':'src/views/'+m[2],'title':(re.search(r"title: '([^']+)'",line) or [None,''])[1]})
source_inventory=[]
for p in sorted(Path('src/views').glob('*.vue')):
 t=p.read_text(encoding='utf-8')
 source_inventory.append({'source':p.as_posix(),'buttons':re.findall(r'<el-button\b[^>]*>([^<]+)</el-button>',t),'functions':re.findall(r'(?:async\s+)?function\s+(\w+)\(',t),'storeCommands':sorted(set(re.findall(r'store\.(\w+)\(',t)))})
inventory={'baseline':'current working tree on 2026-10-25; see root implementation report','routes':routes,'aliases':[{'pattern':'/products','canonical':'/spus','queryPreserved':True},{'pattern':'/products/new','canonical':'/spus/new','queryPreserved':True},{'pattern':'/products/:id','canonical':'identity-dependent /spus/:id, /skus/:id or /materials/:id','note':'sku query chooses true record kind; add/copySku enters SKU creation'},{'pattern':'/columns','canonical':'/spus?panel=columns','note':'through /products redirect'}],'sourceInventory':source_inventory,'scopeNote':'All router component routes including hidden/dynamic pages are inventoried; guide routes and columns query are registered in guide content. Forbidden is an auxiliary state; aliases are separate and do not duplicate canonical denominators.'}
Path('docs/business-guide/route-source-inventory.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2),encoding='utf-8')
print('Canonical component routes',len(routes),'view files',len(source_inventory))
# Each row is deliberately authored for its real page. Ten-section assembly does not invent actions.
P=[]
def page(slug,title,paths,source,purpose,objects,prerequisites,steps,result,limits,failures,example,actions,rules=(),historical=False,formal=True,status='verified'):
 P.append(dict(slug=slug,title=title,patterns=paths,source=source,purpose=purpose,objects=objects,prerequisites=prerequisites,steps=steps,result=result,limits=limits,failures=failures,example=example,actions=list(actions),rules=list(rules),historical=historical,formal=formal,status=status))
